// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FinanceNetting) predicate.FinanceNetting {
	return predicate.FinanceNetting(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FinanceNetting) predicate.FinanceNetting {
	return predicate.FinanceNetting(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FinanceNetting) predicate.FinanceNetting {
	return predicate.FinanceNetting(sql.NotPredicates(p))
}
